<?php
/**
 * `GET /bcm/v1/products/{id}/variations` (T20; SPEC §4.2, §8, §12.1): a
 * product's variations as `{ items, pagination }` in WooCommerce's order,
 * each with its registry fields, `parent_id`, `parent_name` and an attribute
 * summary such as "Blue / Large"; `per_page` capped at 100; arguments and
 * schema generated by RouteSchema; 200 with no items for a product with no
 * variations; 404 `bcm_not_found` for an id that is not a product; a fixed
 * query count whatever the page size; no product object built.
 *
 * Runs over the seeded catalogue in tests/Unit/Query/SeededCatalogue.php,
 * the stub `$wpdb` answering the real prepared statements through
 * tests/Support/SqlEvaluator.php. The wp-env assertion that the route's
 * total equals `count( wc_get_product( $id )->get_children() )` on a real
 * WooCommerce catalogue is still to run.
 *
 * @package BulkCatalogueManager
 * @license GPL-3.0-or-later
 */

declare( strict_types = 1 );

namespace BulkCatalogueManager\Tests\Unit\Rest;

use BulkCatalogueManager\Fields\Registry;
use BulkCatalogueManager\Plugin;
use BulkCatalogueManager\Query\Hydrator;
use BulkCatalogueManager\Rest\Access;
use BulkCatalogueManager\Rest\RouteSchema;
use BulkCatalogueManager\Rest\VariationsController;
use BulkCatalogueManager\Tests\Unit\Query\SeededCatalogue;
use PHPUnit\Framework\TestCase;

require_once dirname( __DIR__ ) . '/Query/SeededCatalogue.php';

final class VariationsRouteTest extends TestCase {
	private const ROUTE = '/bcm/v1/products/(?P<id>[\d]+)/variations';

	protected function setUp(): void {
		self::boot();
	}

	/**
	 * Reset the stubs, log in a shop manager, register the routes and seed.
	 *
	 * @param array<int, array<string, mixed>> $extra Extra seeded rows.
	 */
	private static function boot( array $extra = [] ): void {
		bcm_test_reset();
		$GLOBALS['bcm_test']['logged_in']                  = true;
		$GLOBALS['bcm_test']['caps']['manage_woocommerce'] = true;
		( new Plugin() )->boot();
		do_action( 'rest_api_init' );
		SeededCatalogue::seed( $extra );
	}

	/**
	 * Dispatch a GET to /bcm/v1/products/{id}/variations.
	 *
	 * @param int|string           $id     Product id as it appears in the path.
	 * @param array<string, mixed> $params Query parameters.
	 */
	private static function get( int|string $id, array $params = [] ): \WP_REST_Response|\WP_Error {
		$request = new \WP_REST_Request( 'GET', '/bcm/v1/products/' . $id . '/variations' );
		foreach ( $params as $key => $value ) {
			$request->set_param( $key, $value );
		}
		return rest_get_server()->dispatch( $request );
	}

	/**
	 * Queries a read costs: `$wpdb` statements, the read stubs' cache misses and term reads.
	 */
	private static function cost(): int {
		return bcm_test_query_count() + count( $GLOBALS['bcm_test']['get_terms_calls'] ?? [] );
	}

	public function test_the_route_registers_with_generated_arguments_and_schema(): void {
		$route = $GLOBALS['bcm_test']['routes'][ self::ROUTE ] ?? null;
		$this->assertNotNull( $route );
		$this->assertSame( 'GET', $route[0]['methods'] );
		$this->assertSame( [ Access::class, 'can_read' ], $route[0]['permission_callback'] );
		$args = ( new RouteSchema( Registry::instance() ) )->variation_args();
		$this->assertSame( array_keys( $args ), array_keys( $route[0]['args'] ) );
		$this->assertSame( [ 'id', 'page', 'per_page', 'fields' ], array_keys( $args ) );
		foreach ( $route[0]['args'] as $name => $arg ) {
			$this->assertTrue( is_callable( $arg['validate_callback'] ) && is_callable( $arg['sanitize_callback'] ), $name );
		}
		$schema = call_user_func( $route['schema'] );
		$this->assertSame( VariationsController::TITLE, $schema['title'] );
		$this->assertSame( ( new VariationsController( new Registry() ) )->get_item_schema(), $schema );
		foreach ( [ Hydrator::PARENT_ID, Hydrator::PARENT_NAME, Hydrator::ATTRIBUTE_SUMMARY, Hydrator::ATTRIBUTES, Hydrator::THUMBNAIL_URL ] as $extra ) {
			$this->assertArrayHasKey( $extra, $schema['properties'] );
		}
		foreach ( Registry::instance()->keys() as $key ) {
			$this->assertArrayHasKey( $key, $schema['properties'], "The $key field." );
		}
	}

	public function test_a_product_s_variations_come_in_woocommerce_order_with_their_fields_and_attributes(): void {
		$response = self::get( 103 );
		$this->assertSame( 200, $response->get_status() );
		$data = $response->get_data();
		$this->assertSame(
			[
				'page'       => 1,
				'perPage'    => 25,
				'total'      => 2,
				'totalPages' => 1,
			],
			$data['pagination']
		);
		$this->assertSame( [ 202, 201 ], array_column( $data['items'], 'id' ), 'Menu order, then id; the trashed variation is left out.' );

		[ $green, $blue ] = $data['items'];
		$this->assertSame( array_merge( [ 'id', 'parent_id' ], array_diff( Registry::instance()->keys(), [ 'id' ] ), [ Hydrator::THUMBNAIL_URL, Hydrator::PARENT_NAME, Hydrator::ATTRIBUTE_SUMMARY, Hydrator::ATTRIBUTES ] ), array_keys( $blue ), 'Every registry field, then the extras.' );
		$expected = [
			'parent_id'         => 103,
			'parent_name'       => 'Rain Jacket',
			'attribute_summary' => 'Blue / Large',
			'name'              => 'Rain Jacket - Blue, Large',
			'type'              => 'variation',
			'status'            => 'publish',
			'sku'               => 'JACKET-BL-L',
			'regular_price'     => '60',
			'stock_status'      => 'instock',
			'manage_stock'      => true,
			'stock_quantity'    => 3,
			'shipping_class_id' => 40,
		];
		foreach ( $expected as $key => $value ) {
			$this->assertSame( $value, $blue[ $key ], $key );
		}
		$this->assertSame( 'Dark Green / Any Size', $green['attribute_summary'], 'A term slug reads as its name; an open attribute as "Any".' );
		$this->assertSame(
			[
				[
					'label' => 'Colour',
					'value' => 'Blue',
				],
				[
					'label' => 'Size',
					'value' => 'Large',
				],
			],
			$blue['attributes'],
			'The summary\'s pairs, in its order: the taxonomy\'s label and term name, the custom attribute\'s name and value.'
		);
		$this->assertSame(
			[
				[
					'label' => 'Colour',
					'value' => 'Dark Green',
				],
				[
					'label' => 'Size',
					'value' => '',
				],
			],
			$green['attributes'],
			'An open attribute has an empty value.'
		);
		$this->assertSame( 'private', $green['status'] );
		$this->assertSame( 'outofstock', $green['stock_status'] );

		$schema = call_user_func( $GLOBALS['bcm_test']['routes'][ self::ROUTE ]['schema'] );
		foreach ( $data['items'] as $item ) {
			$this->assertTrue( rest_validate_value_from_schema( $item, $schema, 'item' ), 'Each item validates against the registered schema.' );
		}
	}

	public function test_the_total_is_the_product_s_variation_count(): void {
		$products = new \WP_REST_Request( 'GET', '/bcm/v1/products' );
		$products->set_param( 'fields', 'variation_count' );
		$counts = array_column( rest_get_server()->dispatch( $products )->get_data()['items'], 'variation_count', 'id' );
		foreach ( [ 103, 107 ] as $id ) {
			$this->assertSame( $counts[ $id ], self::get( $id )->get_data()['pagination']['total'], "Product $id." );
		}
	}

	public function test_fields_narrow_each_variation_but_the_extras_stay(): void {
		$items = self::get( 103, [ 'fields' => 'sku' ] )->get_data()['items'];
		$this->assertSame(
			[
				'id'                => 201,
				'parent_id'         => 103,
				'sku'               => 'JACKET-BL-L',
				'parent_name'       => 'Rain Jacket',
				'attribute_summary' => 'Blue / Large',
				'attributes'        => [
					[
						'label' => 'Colour',
						'value' => 'Blue',
					],
					[
						'label' => 'Size',
						'value' => 'Large',
					],
				],
			],
			$items[1]
		);
	}

	public function test_per_page_is_capped_at_100_and_pages_run_past_the_end_truthfully(): void {
		$this->assertSame( 100, self::get( 103, [ 'per_page' => '500' ] )->get_data()['pagination']['perPage'] );

		$second = self::get(
			103,
			[
				'per_page' => 1,
				'page'     => 2,
			]
		)->get_data();
		$this->assertSame( [ 201 ], array_column( $second['items'], 'id' ) );
		$this->assertSame(
			[
				'page'       => 2,
				'perPage'    => 1,
				'total'      => 2,
				'totalPages' => 2,
			],
			$second['pagination']
		);

		$past = self::get(
			103,
			[
				'per_page' => 1,
				'page'     => 3,
			]
		);
		$this->assertSame( 200, $past->get_status() );
		$this->assertSame( [], $past->get_data()['items'] );
		$this->assertSame( 2, $past->get_data()['pagination']['total'] );

		self::boot( SeededCatalogue::variable( 300, 3001, 150 ) );
		$many = self::get( 300, [ 'per_page' => 500 ] )->get_data();
		$this->assertCount( 100, $many['items'] );
		$this->assertSame( 150, $many['pagination']['total'] );
		$this->assertSame( range( 3001, 3100 ), array_column( $many['items'], 'id' ) );
	}

	public function test_a_product_with_no_variations_answers_200_with_no_items(): void {
		$response = self::get( 107 );
		$this->assertInstanceOf( \WP_REST_Response::class, $response );
		$this->assertSame( 200, $response->get_status() );
		$this->assertSame(
			[
				'items'      => [],
				'pagination' => [
					'page'       => 1,
					'perPage'    => 25,
					'total'      => 0,
					'totalPages' => 0,
				],
			],
			$response->get_data()
		);
		$this->assertSame( [], self::get( 101 )->get_data()['items'], 'A simple product has none either.' );
	}

	public function test_an_id_that_is_not_a_product_answers_404_before_any_catalogue_query(): void {
		foreach ( [
			'missing'       => 999,
			'a variation'   => 201,
			'trashed'       => 108,
			'an attachment' => 5000,
		] as $case => $id ) {
			self::boot();
			$result = self::get( $id );
			$this->assertInstanceOf( \WP_Error::class, $result, $case );
			$this->assertSame( 'bcm_not_found', $result->get_error_code(), $case );
			$this->assertSame( 404, $result->get_error_data()['status'], $case );
			$this->assertStringNotContainsString( 'bcm_', $result->get_error_message(), 'No code in the sentence.' );
			$this->assertSame( [], preg_grep( '/^SELECT /', $GLOBALS['wpdb']->queries ), "$case reached the catalogue." );
		}

		$zero = self::get( 0 );
		$this->assertSame( 'rest_invalid_param', $zero->get_error_code(), 'Id 0 fails its argument, before the handler.' );
		$this->assertSame( 'rest_no_route', self::get( 'abc' )->get_error_code(), 'The path takes digits only.' );
	}

	public function test_an_anonymous_read_is_refused(): void {
		$GLOBALS['bcm_test']['logged_in'] = false;
		$GLOBALS['bcm_test']['caps']      = [];
		$result                           = self::get( 103 );
		$this->assertSame( 'bcm_forbidden', $result->get_error_code() );
		$this->assertSame( [], $GLOBALS['wpdb']->queries );
	}

	public function test_the_query_count_is_fixed_whatever_the_page_size(): void {
		$costs = [];
		foreach ( [ 5, 25, 60 ] as $per_page ) {
			self::boot( SeededCatalogue::variable( 300, 3001, 60 ) );
			$before = self::cost();
			$items  = self::get( 300, [ 'per_page' => $per_page ] )->get_data()['items'];
			$this->assertCount( $per_page, $items );
			$costs[ $per_page ] = self::cost() - $before;
		}
		$this->assertSame( [ $costs[5], $costs[5], $costs[5] ], array_values( $costs ), (string) wp_json_encode( $costs ) );
		// Product lookup, count, page, posts, meta, terms, price lookup, attribute names. The product's post is
		// already primed by the lookup, no image means no attachment prime, and variations need no variation count.
		$this->assertSame( 8, $costs[5], implode( "\n", $GLOBALS['wpdb']->queries ) );
		$this->assertSame( [], preg_grep( '/^SELECT post_parent AS parent_id, COUNT/', $GLOBALS['wpdb']->queries ) );
		$this->assertCount( 1, $GLOBALS['bcm_test']['get_terms_calls'], 'The attribute terms are named in one read.' );
		$this->assertSame( 'Blue / Small', $items[0]['attribute_summary'] );
		$this->assertSame( 'Dark Green / Medium', $items[1]['attribute_summary'] );
		// With only the name column no field needs meta, yet the attribute summary does: still one prime, not one read per row.
		$narrow = [];
		foreach ( [ 5, 60 ] as $per_page ) {
			self::boot( SeededCatalogue::variable( 300, 3001, 60 ) );
			$before              = self::cost();
			$items               = self::get(
				300,
				[
					'per_page' => $per_page,
					'fields'   => 'name',
				]
			)->get_data()['items'];
			$narrow[ $per_page ] = self::cost() - $before;
			$this->assertSame( 'Blue / Small', $items[0]['attribute_summary'] );
		}
		$this->assertSame( $narrow[5], $narrow[60], (string) wp_json_encode( $narrow ) );
		$this->assertSame( 6, $narrow[5], 'Product lookup, count, page, posts, meta, attribute names.' );
	}

	public function test_no_product_object_is_built_on_a_variation_read(): void {
		$fired = 0;
		add_action(
			'woocommerce_product_read',
			static function () use ( &$fired ): void {
				++$fired;
			}
		);
		$this->assertCount( 2, self::get( 103 )->get_data()['items'] );
		$products = new \WP_REST_Request( 'GET', '/bcm/v1/products' );
		$products->set_param( 'mode', 'variations' );
		$this->assertCount( 2, rest_get_server()->dispatch( $products )->get_data()['items'] );
		$this->assertSame( 0, $fired );
		$this->assertSame( 0, $GLOBALS['bcm_test']['products_built'] ?? 0 );

		$code = (string) file_get_contents( dirname( __DIR__, 3 ) . '/src/Rest/VariationsController.php' );
		$this->assertSame( 0, preg_match( '/wc_get_products?\s*\(|new\s+\\\\?WC_Product|->get_children\s*\(|wc_get_formatted_variation\s*\(/', $code ) );
	}

	public function test_the_attribute_summary_composition(): void {
		$this->assertSame( 'Blue / Large', Hydrator::attribute_summary( [ [ 'Colour', 'Blue' ], [ 'Size', 'Large' ] ] ) );
		$this->assertSame( 'Any Colour / Large', Hydrator::attribute_summary( [ [ 'Colour', '' ], [ 'Size', 'Large' ] ] ) );
		$this->assertSame( 'Blue', Hydrator::attribute_summary( [ [ 'Colour', 'Blue' ] ] ) );
		$this->assertSame( '', Hydrator::attribute_summary( [] ), 'No attributes: nothing, not a separator.' );

		// A term deleted since the variation was saved reads as its slug.
		$GLOBALS['bcm_test']['meta'][201]['attribute_pa_colour'] = 'sky-blue';
		$this->assertSame( 'sky-blue / Large', self::get( 103 )->get_data()['items'][1]['attribute_summary'] );
	}
}
